size_t bit;
	bitmap_t g;
	unsigned i;

	assert(!bitmap_full(bitmap, binfo));

	i = binfo->nlevels - 1;
	g = atomic_load_zu(&bitmap[binfo->levels[i].group_offset], ATOMIC_RELAXED);
	bit = ffs_lu(g);
	while (i > 0) {
		i--;
		g = atomic_load_zu(&bitmap[binfo->levels[i].group_offset + bit], ATOMIC_RELAXED);
		bit = (bit << LG_BITMAP_GROUP_NBITS) + ffs_lu(g);
	}

	/* bit is now the first unset bit index */
	bitmap_set(bitmap, binfo, bit);
	return bit;

